import csv, openpyxl
# 第8日可查的锁定与容量（柜面 as_of 8，未变）
lock={'J01':2,'J02':0,'J03':1,'J04':0,'J05':3,'J06':1,'J07':2,'J08':1,'J09':0,'J10':1,'J11':2,'J12':0}
st={'J01':'东港','J02':'东港','J03':'东港','J04':'西湾','J05':'西湾','J06':'西湾',
    'J07':'南站','J08':'南站','J09':'南站','J10':'北仓','J11':'北仓','J12':'北仓'}
cap={'东港':8,'西湾':7,'南站':8,'北仓':7}
# 第9日已知授权：排期表九日批文额度 + 九日预兑；正数兑入案优先号-1
pai={r['案号']:r for r in csv.DictReader(open('out/排期.csv',encoding='utf-8-sig'))}
auth={r['案号']:r for r in csv.DictReader(open('out/授权.csv',encoding='utf-8-sig'))}
# 九日批文额度/优先：来自第7日签发件核对表
b9={'J01':(7002,2,3),'J02':(2010,3,1),'J03':(2020,4,2),'J04':(7032,5,3),'J05':(2040,5,2),'J06':(7052,2,2),
    'J07':(2060,5,2),'J08':(7072,4,1),'J09':(2080,5,1),'J10':(7092,6,3),'J11':(2100,5,3),'J12':(7112,3,2)}
rows=[]
for c in sorted(lock,key=lambda x:int(x[1:])):
    dui=int(pai[c]['九日预兑']); base=b9[c][1]; pri=b9[c][2]
    ed=base+dui; pr=pri-1 if dui>0 else pri
    rows.append({'案号':c,'站':st[c],'额':ed,'优':pr,'锁':lock[c],'净':max(0,ed-lock[c]),'基础':base,'兑':dui,'批文':b9[c][0]})
rows.sort(key=lambda r:(r['优'],r['案号']))
wb=openpyxl.load_workbook('out/预约.xlsx')
ws=wb['容量']
for i,s in enumerate(['东港','西湾','南站','北仓']):
    ws.cell(row=2+i,column=1,value=s)
    ws.cell(row=2+i,column=2,value=cap[s]-sum(lock[c] for c in lock if st[c]==s))
q=wb['队列']
for r in range(2,14):
    for c in range(1,6): q.cell(row=r,column=c,value=None)
for i,r in enumerate(rows):
    row=2+i
    q.cell(row=row,column=1,value=r['案号']); q.cell(row=row,column=2,value=r['站']); q.cell(row=row,column=3,value=r['净'])
    q.cell(row=row,column=4,value=f"=MIN(C{row},MAX(0,VLOOKUP(B{row},容量!$A$2:$B$5,2,0)-SUMIF($B$1:B{row-1},B{row},$D$1:D{row-1})))")
    q.cell(row=row,column=5,value=f"=C{row}-D{row}")
wb.save('out/预约.xlsx')
for r in rows: print(r['案号'],r['站'],'批文',r['批文'],'基础',r['基础'],'+兑',r['兑'],'额',r['额'],'优',r['优'],'锁',r['锁'],'净',r['净'])
print('容量',{s:cap[s]-sum(lock[c] for c in lock if st[c]==s) for s in cap})
